    .asciz "ts        task                 Suspend a task"
    .asciz "tr        task                 Resume a task"
    .asciz "tw        task                 Print pending task detailed info"
    .asciz "w         [task]               Print pending task info"
    .asciz "d         [adr[,nunits[,width]]] Display memory"
    .asciz "m         adr[,width]          Modify memory"
    .asciz "mRegs     [reg[,task]]         Modify a task's registers interactively"
    .asciz "pc        [task]               Return task's program counter"
